1	export type Monster =
2	  | "sphinx"
3	  | "undead-warrior"
4	  | "zombie"
5	  | "hydra"
6	  | "cyclops"
7	  | "orthrus"
8	  | "chimera";
9	
10	export interface Card {
11	  monster: Monster;
12	  rank?: 1 | 2 | 3;
13	}
14	
15	const VARIETY_THRESHOLD = 3;
16	const POINTS_PER_SPHINX_BEYOND_THRESHOLD = 2;
17	const POINTS_PER_SPHINX = 1;
18	
19	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
20	
21	// `rank` is deliberately excluded from the key: rank variants (e.g. Undead
22	// Warrior ranks 1-3) are variants of one monster and count as a single type.
23	const countDistinctMonsterTypes = (army: Card[]): number =>
24	  new Set(army.map((card) => card.monster)).size;
25	
26	const pointsPerSphinx = (army: Card[]): number =>
27	  countDistinctMonsterTypes(army) > VARIETY_THRESHOLD
28	    ? POINTS_PER_SPHINX_BEYOND_THRESHOLD
29	    : POINTS_PER_SPHINX;
30	
31	export const scoreArmy = (army: Card[]): number =>
32	  army.filter(isSphinx).length * pointsPerSphinx(army);
33
